function rng(seed){let n=2166136261;for(let c of String(seed)){n^=c.charCodeAt(0);n=Math.imul(n,16777619)}return()=>{n=(n+0x6D2B79F5)|0;let t=Math.imul(n^n>>>15,n|1);t^=t+Math.imul(t^t>>>7,t|61);return ((t^t>>>14)>>>0)/4294967296}}
const PAIRS=[[[0,1],[2,3]],[[0,3],[1,2]],[[0,2],[1,3]]],DIR=[[0,-1],[1,0],[0,1],[-1,0]];
function exitFor(t,e){return PAIRS[t].find(p=>p.includes(e)).find(d=>d!==e)}
function position(p){let a=[[.5,0],[1,.5],[.5,1],[0,.5]][p.entry],b=[[.5,0],[1,.5],[.5,1],[0,.5]][p.exit];if((p.entry+2)%4===p.exit)return{x:p.x+a[0]+(b[0]-a[0])*p.u,y:p.y+a[1]+(b[1]-a[1])*p.u};let cx=p.entry===1||p.exit===1?1:0,cy=p.entry===2||p.exit===2?1:0,ang=Math.atan2(a[1]-cy,a[0]-cx),end=Math.atan2(b[1]-cy,b[0]-cx),d=Math.atan2(Math.sin(end-ang),Math.cos(end-ang));return{x:p.x+cx+.5*Math.cos(ang+d*p.u),y:p.y+cy+.5*Math.sin(ang+d*p.u)}}
function scenario(c){let r=rng(c.seed+':traffic'),out=[];for(let i=0;i<c.duration*c.flux;i++){let side=Math.floor(r()*4),x=side===1?c.cols-1:side===3?0:Math.floor(r()*c.cols),y=side===0?0:side===2?c.rows-1:Math.floor(r()*c.rows);out.push({time:i/c.flux,x,y,entry:side})}return out}
function createSim(genome,c,schedule){return{tiles:Uint8Array.from(genome),c,schedule,at:0,time:0,particles:[],collisions:0,exits:0,bins:Array(c.duration).fill(0),r:rng(c.seed+':impacts'),sparks:[]}}
function tick(s,dt){const c=s.c;s.time=Math.min(c.duration,s.time+dt);while(s.at<s.schedule.length&&s.schedule[s.at].time<s.time){let p={...s.schedule[s.at++],u:0};p.exit=exitFor(s.tiles[p.y*c.cols+p.x],p.entry);s.particles.push(p)}let dead=new Set();for(let i=0;i<s.particles.length;i++){let p=s.particles[i];p.exit=exitFor(s.tiles[p.y*c.cols+p.x],p.entry);p.u+=dt*c.speed/((p.entry+2)%4===p.exit?1:Math.PI/4);if(p.u>=1){let e=p.exit;p.x+=DIR[e][0];p.y+=DIR[e][1];if(p.x<0||p.x>=c.cols||p.y<0||p.y>=c.rows){dead.add(i);s.exits++;continue}p.entry=(e+2)%4;p.exit=exitFor(s.tiles[p.y*c.cols+p.x],p.entry);p.u=0}}
if(s.particles.length>40){let buckets=new Map(),positions=s.particles.map((p,i)=>dead.has(i)?null:position(p));for(let i=0;i<positions.length;i++){let a=positions[i];if(!a||dead.has(i))continue;let bx=Math.floor(a.x/.24),by=Math.floor(a.y/.24),hit=-1;for(let dx=-1;dx<=1&&hit<0;dx++)for(let dy=-1;dy<=1&&hit<0;dy++)for(let j of buckets.get((bx+dx)+','+(by+dy))||[]){let b=positions[j];if(!dead.has(j)&&Math.hypot(a.x-b.x,a.y-b.y)<.21){hit=j;break}}if(hit>=0){let b=positions[hit],x=Math.max(0,Math.min(c.cols-1,Math.floor((a.x+b.x)/2))),y=Math.max(0,Math.min(c.rows-1,Math.floor((a.y+b.y)/2))),idx=y*c.cols+x;s.tiles[idx]=(s.tiles[idx]+1+Math.floor(s.r()*2))%3;s.collisions++;s.bins[Math.min(c.duration-1,Math.floor(s.time))]++;s.sparks.push({x:x+.5,y:y+.5,life:.35});dead.add(i);dead.add(hit)}else{let k=bx+','+by;if(!buckets.has(k))buckets.set(k,[]);buckets.get(k).push(i)}}}else{let deadCount=dead.size;if(s.particles.length-deadCount>1){let positions=new Array(s.particles.length);for(let i=0;i<s.particles.length;i++){if(dead.has(i))continue;let p=s.particles[i];for(let j=0;j<i;j++){if(dead.has(j))continue;let q=s.particles[j];if(Math.abs(p.x-q.x)>1||Math.abs(p.y-q.y)>1)continue;let a=positions[i]||(positions[i]=position(p)),b=positions[j]||(positions[j]=position(q)),dx=a.x-b.x,dy=a.y-b.y;if(dx*dx+dy*dy<.0441){let x=Math.max(0,Math.min(c.cols-1,Math.floor((a.x+b.x)/2))),y=Math.max(0,Math.min(c.rows-1,Math.floor((a.y+b.y)/2))),idx=y*c.cols+x;s.tiles[idx]=(s.tiles[idx]+1+Math.floor(s.r()*2))%3;s.collisions++;s.bins[Math.min(c.duration-1,Math.floor(s.time))]++;s.sparks.push({x:x+.5,y:y+.5,life:.35});dead.add(i);dead.add(j);break}}}}}s.particles=s.particles.filter((p,i)=>!dead.has(i));s.sparks=s.sparks.filter(p=>(p.life-=dt)>0)}
function evaluate(genome,c,schedule,onProgress){let s=createSim(genome,c,schedule);for(let i=0;i<c.duration*60;i++){tick(s,1/60);if(onProgress&&i%120===0)onProgress(s.time,s.collisions)}return s}
